1|/* Player row inside the bottom band: transport and now playing. The
2|   music-style control (stickers, Chopin toggle) lives in
3|   music-style-control.css. */
4|
5|.player {
6|  display: flex;
7|  align-items: center;
8|  gap: 10px;
9|  flex: 1 1 auto;
10|  min-width: 0;
11|  font-family: var(--font-ui);
12|  font-size: 13px;
13|}
14|
15|.player button:focus-visible,
16|.player input:focus-visible,
17|.player a:focus-visible {
18|  outline: 2px solid var(--color-accent);
19|  outline-offset: 2px;
20|}
21|
22|.player .skip {
23|  display: inline-flex;
24|  align-items: center;
25|  justify-content: center;
26|  width: 34px;
27|  height: 34px;
28|  padding: 0;
29|  border: 1px solid var(--color-text);
30|  border-radius: 6px;
31|  background: var(--color-surface);
32|  color: var(--color-text);
33|  cursor: pointer;
34|  flex: none;
35|}
36|
37|.player .skip svg {
38|  stroke: currentColor;
39|  fill: none;
40|  stroke-width: 1.5;
41|}
42|
43|.player .skip:hover:not(:disabled) {
44|  border-color: var(--color-accent-hover);
45|  color: var(--color-accent-hover);
46|}
47|
48|.player .skip:disabled {
49|  opacity: 0.3;
50|  cursor: default;
51|}
52|
53|.player .play {
54|  background: var(--color-accent-fill);
55|  border-color: var(--color-accent-fill);
56|  color: #fff;
57|}
58|
59|.player .play svg {
60|  stroke: #fff;
61|}
62|
63|.player .play:hover:not(:disabled) {
64|  color: #fff;
65|}
66|
67|.player-track {
68|  font-family: var(--font-book);
69|  font-style: italic;
70|  font-size: 15.5px;
71|  line-height: 1.35;
72|  flex: 0 1 300px;
73|  width: 300px;
74|  min-width: 0;
75|  max-width: 300px;
76|  overflow: hidden;
77|}
78|
79|.player-track-inner {
80|  display: inline-block;
81|  white-space: nowrap;
82|}
83|
84|.player-track[data-overflow="1"] {
85|  mask-image: linear-gradient(to right, #000 calc(100% - 16px), transparent);
86|}
87|
88|.player-track[data-overflow="1"] .player-track-inner {
89|  animation: player-marquee var(--marquee-duration, 6000ms) linear infinite alternate;
90|}
91|
92|@keyframes player-marquee {
93|  0%,
94|  15% {
95|    transform: translateX(0);
96|  }
97|  85%,
98|  100% {
99|    transform: translateX(calc(-1 * var(--marquee-shift, 0px)));
100|  }
101|}
102|
103|@media (prefers-reduced-motion: reduce) {
104|  .player-track[data-overflow="1"] {
105|    mask-image: none;
106|  }
107|  .player-track[data-overflow="1"] .player-track-inner {
108|    animation: none;
109|    transform: none;
110|    display: block;
111|    overflow: hidden;
112|    text-overflow: ellipsis;
113|  }
114|}
115|
116|.player[data-reduced-motion="true"] .player-track[data-overflow="1"] {
117|  mask-image: none;
118|}
119|
120|.player[data-reduced-motion="true"] .player-track[data-overflow="1"] .player-track-inner {
121|  animation: none;
122|  transform: none;
123|  display: block;
124|  overflow: hidden;
125|  text-overflow: ellipsis;
126|}
127|
128|.player-track a {
129|  color: var(--color-accent);
130|  text-decoration: underline;
131|  text-underline-offset: 3px;
132|  white-space: nowrap;
133|}
134|
135|.player-track a svg {
136|  stroke: currentColor;
137|  fill: none;
138|  stroke-width: 1.5;
139|  vertical-align: -1px;
140|}
141|
142|.player-volume {
143|  display: inline-flex;
144|  align-items: center;
145|  color: var(--color-text-muted);
146|  flex: none;
147|}
148|
149|.player-volume input {
150|  width: 64px;
151|  accent-color: var(--color-accent);
152|  cursor: pointer;
153|}
154|
155|.player-note {
156|  flex: 1 1 auto;
157|  font-family: var(--font-ui);
158|  font-size: 13px;
159|  color: var(--color-text-muted);
160|  margin: 0;
161|  text-align: center;
162|}
163|

